# Demo input uses the pattern I should use for each tile
demo_input = [
    [0, 7, 0],
    [7, 7, 7],
    [0, 7, 0]
]

# Build output where each tile is the demo input pattern
output = [[0]*9 for _ in range(9)]

for r in range(3):
    for c in range(3):
        tile = demo_input  # Use the demo's pattern for every tile
        for tr in range(3):
            for tc in range(3):
                output[r*3 + tr][c*3 + tc] = tile[tr][tc]

print("If each tile = demo input pattern:")
for row in output:
    print(row)

# Build correct tile
test_nonzeros = [(0, 2), (1, 0), (1, 1), (2, 1)]

def flip_pos(r, c):
    return (2 - r, 2 - c)

disabled = set()
for r, c in test_nonzeros:
    fr, fc = flip_pos(r, c)
    disabled.add((fr, fc))

print("Disabled positions:", sorted(disabled))

tile_content = [[0] * 3 for _ in range(3)]
for r in range(3):
    for c in range(3):
        if (r, c) not in disabled:
            tile_content[r][c] = 3

print("\nTile content:")
for row in tile_content:
    print(row)

# Build full output
output = [[0]*9 for _ in range(9)]
for r in range(3):
    for c in range(3):
        if test_input[r][c] != 0:
            # Place tile content at output[r*3:(r+1)*3][c*3:(c+1)*3]
            for tr in range(3):
                for tc in range(3):
                    output[r*3 + tr][c*3 + tc] = tile_content[tr][tc]

print("\nFull output:")
for row in output:
    print(row)
